import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA source (inline) for fp16 transposed convolution (square kernel)
# ----------------------------------------------------------------------
src = r'''
#include <cuda_fp16.h>
#include <cuda_runtime.h>

extern "C" __global__
void conv_transpose2d_fp16(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    float* __restrict__ out_fp32,
    int batch,
    int in_channels,
    int out_channels,
    int H_in,
    int W_in,
    int K,
    int stride,
    int padding,
    int output_padding,
    int groups,
    int H_out,
    int W_out)
{
    // One thread per (n, ic, h, w)
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * in_channels * H_in * W_in;
    if (idx >= total) return;

    int w_in = idx % W_in;
    int tmp = idx / W_in;
    int h_in = tmp % H_in;
    tmp = tmp / H_in;
    int ic = tmp % in_channels;
    int n = tmp / in_channels;

    // Load input value (half) and promote to float
    __half in_h = input[idx];
    float in_f = __half2float(in_h);

    int group_idx = ic / (in_channels / groups);
    int ic_per_group = in_channels / groups;
    int oc_per_group = out_channels / groups;

    // Pointer offset for weight of this input channel within its group
    const __half* w_ptr = weight + ic * oc_per_group * K * K;

    for (int kh = 0; kh < K; ++kh) {
        int h_out = h_in * stride - padding + kh;
        if (h_out < 0 || h_out >= H_out) continue;
        for (int kw = 0; kw < K; ++kw) {
            int w_out = w_in * stride - padding + kw;
            if (w_out < 0 || w_out >= W_out) continue;

            int out_base = ((n * out_channels) + (group_idx * oc_per_group)) * H_out * W_out
                         + h_out * W_out + w_out;

            // Loop over output channels within the group
            for (int ocg = 0; ocg < oc_per_group; ++ocg) {
                // weight layout: (in_channels, out_channels_per_group, K, K)
                int w_idx = ((ic * oc_per_group) + ocg) * K * K + kh * K + kw;
                float w_f = __half2float(w_ptr[w_idx]);
                atomicAdd(&out_fp32[out_base + ocg * H_out * W_out], in_f * w_f);
            }
        }
    }
}

// ------------------------------------------------------------------
// Add bias (fp16) to fp32 output buffer
// ------------------------------------------------------------------
extern "C" __global__
void add_bias_fp16(float* __restrict__ out_fp32,
                  const __half* __restrict__ bias,
                  int batch,
                  int out_channels,
                  int H_out,
                  int W_out)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch * out_channels * H_out * W_out;
    if (idx >= total) return;

    int oc = (idx / (H_out * W_out)) % out_channels;
    float b = __half2float(bias[oc]);
    out_fp32[idx] += b;
}

// ------------------------------------------------------------------
// Convert fp32 buffer to fp16 output tensor
// ------------------------------------------------------------------
extern "C" __global__
void fp32_to_fp16(const float* __restrict__ src,
                  __half* __restrict__ dst,
                  int N)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= N) return;
    dst[i] = __float2half(src[i]);
}
'''

# Compile the inline extension
conv_ext = load_inline(name='conv_transpose2d_fp16_ext',
                       cpp_sources='',
                       cuda_sources=src,
                       functions=['conv_transpose2d_fp16',
                                  'add_bias_fp16',
                                  'fp32_to_fp16'],
                       verbose=False)

# ----------------------------------------------------------------------
# PyTorch module using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Custom transposed 2D convolution (square kernel) for fp16 tensors.
    Mirrors torch.nn.ConvTranspose2d API.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 output_padding: int = 0,
                 groups: int = 1,
                 bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size if isinstance(kernel_size, int) else kernel_size[0]
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.use_bias = bias

        # weight shape: (in_channels, out_channels // groups, K, K)
        self.weight = nn.Parameter(
            torch.empty(in_channels,
                        out_channels // groups,
                        self.kernel_size,
                        self.kernel_size,
                        dtype=torch.float16,
                        device='cuda')
        )
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        if self.use_bias:
            self.bias = nn.Parameter(torch.empty(out_channels,
                                                 dtype=torch.float16,
                                                 device='cuda'))
            nn.init.zeros_(self.bias)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x: (N, C_in, H_in, W_in) fp16 tensor
        Returns:
            y: (N, C_out, H_out, W_out) fp16 tensor
        """
        assert x.dtype == torch.float16, "Input must be fp16"
        N, C_in, H_in, W_in = x.shape
        K = self.kernel_size
        stride = self.stride
        pad = self.padding
        out_pad = self.output_padding
        groups = self.groups

        H_out = (H_in - 1) * stride - 2 * pad + K + out_pad
        W_out = (W_in - 1) * stride - 2 * pad + K + out_pad

        # Allocate temporary fp32 output buffer
        out_fp32 = torch.empty(N,
                               self.out_channels,
                               H_out,
                               W_out,
                               dtype=torch.float32,
                               device='cuda')
        out_fp32.zero_()

        # Launch main kernel
        total_threads = N * C_in * H_in * W_in
        threads_per_block = 256
        blocks = (total_threads + threads_per_block - 1) // threads_per_block

        conv_ext.conv_transpose2d_fp16(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.use_bias else torch.empty(0, device='cuda', dtype=torch.float16),
            out_fp32,
            N,
            C_in,
            self.out_channels,
            H_in,
            W_in,
            K,
            stride,
            pad,
            out_pad,
            groups,
            H_out,
            W_out,
            grid=(blocks,),
            block=(threads_per_block,)
        )

        # Add bias if needed
        if self.use_bias:
            total_out = N * self.out_channels * H_out * W_out
            bias_blocks = (total_out + threads_per_block - 1) // threads_per_block
            conv_ext.add_bias_fp16(
                out_fp32,
                self.bias,
                N,
                self.out_channels,
                H_out,
                W_out,
                grid=(bias_blocks,),
                block=(threads_per_block,)
            )

        # Convert fp32 buffer back to fp16 output tensor
        out_fp16 = torch.empty_like(out_fp32, dtype=torch.float16)
        total_out = out_fp32.numel()
        conv_blocks = (total_out + threads_per_block - 1) // threads_per_block
        conv_ext.fp32_to_fp16(
            out_fp32,
            out_fp16,
            total_out,
            grid=(conv_blocks,),
            block=(threads_per_block,)
        )

        return out_fp16

# ----------------------------------------------------------------------
# Test harness (mirrors the reference)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 8
    in_channels = 64
    out_channels = 64
    kernel_size = 3
    height = 1024
    width = 1024

    def get_inputs():
        x = torch.rand(batch_size, in_channels, height, width,
                       dtype=torch.float16, device='cuda')
        return [x]

    def get_init_inputs():
        return [in_channels, out_channels, kernel_size]

    # Example usage
    init_args = get_init_inputs()
    model = ModelNew(*init_args).cuda()
    x = get_inputs()[0]
    y = model(x)
    print(f"Output shape: {y.shape}, dtype: {y.dtype}")
